      expect(req.method).toBe('POST')
      expect(req.url).toBe('https://discord.com/api/webhooks/test-id/test-token')
      expect(req.json).toEqual({
        content: 'recAbCdEfGhIjKlMnO',
        embeds: [
          {
            fields: [
              { name: 'Name', value: 'John Doe', inline: true },
              { name: 'Email', value: 'john@example.com', inline: true },
              { name: 'Age', value: '30', inline: true }
            ],
            timestamp: '2023-04-10T12:34:56.000Z'
          }
        ]
      })
      return jsonResponse({ id: 'msg-123', channel_id: 'chan-456', content: 'recAbCdEfGhIjKlMnO' })
    })
    const config: ConnectorConfig = {
      discordWebhookId: 'test-id',
      discordWebhookToken: 'test-token',
      fetch
    }
    const payload: AirtableWebhookPayload = {
      payloads: [
        {
          id: 'recAbCdEfGhIjKlMnO',
          baseTransactionNumber: 1,
          timestamp: '2023-04-10T12:34:56.000Z',
          inputs: {
            recordId: 'recAbCdEfGhIjKlMnO',
            fields: {
