              Email: 'john@example.com',
              Age: 30
            },
            createdTime: '2023-04-10T12:34:56.000Z'
          }
        }
      ]
    }
    const result = await handle(payload, config)
    expect(result.messageId).toBe('msg-123')
    expect(result.channelId).toBe('chan-456')
    expect(result.processedRecords).toBe(1)
    expect(calls.length).toBe(1)
  })

  it('processes multiple records in payloads array', async () => {
    let callCount = 0
