  })

  it('converts field values to strings in embed', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      const embed = (req.json as { embeds: Array<{ fields: Array<{ value: string }> }> }).embeds[0]
      expect(embed.fields.find(f => f.name === 'Age')?.value).toBe('30')
